dict(id="hide-and-seek-protocol", name="'Grail Castle' hide-and-seek protocol (telephone + clock + USGS map)", category="map-geography",
 summary="Penn's general game: a hider tells a seeker where an object is using only one-ring calls at chosen clock times. The times name a USGS sheet, two benchmarks with clock-time elevations, and two hour-hand azimuths. Penn says this is how he was 'led directly' to Goose Pond.",
 rules="Agree on a USGS quadrangle, identified by a number expressible as a clock time. Pick two surveyed points whose numbers are valid clock times (100-1259). Superimpose a clock face on each (12 = due north) and express each line to the object as an hour-hand time. Send no more than five one-ring calls (the two BM numbers and the two azimuths). 720 half-degree steps; within 2 nautical miles this beats lat/long to the second. The rules 'must be unknown to the seeker'. Clock times can also be written in binary to spell Morse words.",
 examples=[
  X("Penn's example: BM 125 and BM 510", "lines at 2:30 and 6:17 -> four calls at 1:25, 2:30, 5:10, 6:17", "", ('ev','12*60',720)),
  X("'150, as I would redivide it, were I a hider'", "1 001 0110 = digit UP", "Ecphorizer #46: Penn writing as the hider.", ('ev',"int('1'+bits('UP'),2)",150)),
 ],
 claims="Penn claims O'Hare used this protocol to give the burial spot. This is his claim.",
 first_seen="1984 (Times 17); published as a game in Ecphorizer #46, Jun 1985",
 citations=["Ecphorizer #46, Jun 1985, 'Hide and Seek'", "T17:201-205"],
 demo=D("none", "", ""),
 related=["clock-face-azimuth","benchmark-numbers","call-time-morse","penn-puzzle-setting"]),

